# Scored file: envelope_encrypt.py\n# Performs envelope encryption using AWS KMS for key management and local AES for data encryption\n\nimport os\nimport json\nimport boto3\nfrom botocore.exceptions import ClientError\n\nfrom security_client import get_kms_client\nfrom security_models import PlaintextPayload, EncryptedEnvelope\n\ndef envelope_encrypt(payload: str) -> EncryptedEnvelope:\n    \"\"\"Encrypt a plaintext payload with envelope encryption.\n\n    Returns an EncryptedEnvelope containing:\n      - encrypted_data_key: ciphertext of the data key (encrypted by KMS)\n      - ciphertext: payload encrypted with the plaintext data key\n    \"\"\"\n    client = get_kms_client()\n    key_id = os.getenv('AWS_KMS_KEY_ID')\n    if not key_id:\n        raise RuntimeError('AWS_KMS_KEY_ID environment variable not set')\n\n    try:\n        # Generate a new data key (plaintext and ciphertext) via KMS\n        resp = client.generate_data_key(\n            KeyId=key_id,\n            KeySpec='AES_256'\n        )\n        data_key = resp['Plaintext']  # plaintext AES key (bytes)\n        encrypted_key = resp['CiphertextBlob']  # encrypted data key (bytes)\n\n        # Encrypt the payload locally with AES-256-CBC\n        ciphertext = _aes_encrypt(payload.encode('utf-8'), data_key)\n\n        return EncryptedEnvelope(\n            encrypted_data_key=encrypted_key,\n            ciphertext=ciphertext\n        )\n    except ClientError as e:\n        raise RuntimeError(f\"KMS error: {e}\") from e\n\ndef _aes_encrypt(data: bytes, key: bytes) -> bytes:\n    from Crypto.Cipher import AES\n    from Crypto.Util.Padding import pad\n    iv = os.urandom(16)\n    cipher = AES.new(key, AES.MODE_CBC, iv)\n    ct = cipher.encrypt(pad(data, AES.block_size))\n    return iv + ct  # prepend IV for later decryption\n\nif __name__ == \"__main__\":\n    sample = \"Sensitive data that needs protection.\"\n    envelope = envelope_encrypt(sample)\n    print(json.dumps({\n        'encrypted_data_key': envelope.encrypted_data_key.decode('base64'),\n        'ciphertext': envelope.ciphertext.decode('base64')\n    }))\n